      "path": "pyproject.toml",
      "content": "[project]\nname = \"reme-ai\"\ndynamic = [\"version\"]\ndescription = \"Remember Me, Refine Me.\"\nreadme = \"README.md\"\nauthors = [\n    { name = \"EconML team of Alibaba Tongyi Lab\", email = \"jinli.yl@alibaba-inc.com\" },\n]\nlicense = \"Apache-2.0\"\nrequires-python = \">=3.11\"\nkeywords = [\"llm\", \"memory\", \"agent\", \"agentscope\", \"ai\", \"mcp\", \"reme\"]\n\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Operating System :: OS Independent\",\n    \"Intended Audience :: Developers\",\n    \"Intended Audience :: Science/Research\",\n    \"Topic :: Scientific/Engineering :: Artificial Intelligence\",\n]\n\ndependencies = [\n    \"aiofiles>=25.1.0\",\n    \"croniter>=6.2.4\",\n    \"fastapi>=0.162.0\",\n    \"fastmcp>=4.1.4,<5\",\n    \"httpx[socks]>=0.28.1\",\n    \"loguru>=0.7.3\",\n    \"mcp>=2.3.0,<3\",\n    \"mistletoe>=1.6.0\",\n    \"numpy>=2.4.6; python_version < '3.12'\",\n    \"numpy>=2.5.4; python_version >= '3.12'\",\n    \"openai>=3.40.0\",\n    \"psutil>=7.2.2\",\n    \"pydantic>=2.14.1\",\n    \"python-frontmatter>=1.3.0\",\n    \"pyyaml>=6.0.3\",\n    \"rich>=15.0.0\",\n    \"uvicorn>=0.54.0\",\n    \"watchfiles>=1.3.0\",\n    \"zstandard>=0.25.0\",\n]\n\n[project.optional-dependencies]\nas = [\n    \"agentscope[model-ollama]==2.0.11\",\n]\ndecision = [\n    \"agentscope[classifier-jev]==2.0.11\",\n]\nweb = [\n    \"reme_studio\",\n]\ncore = [\n    \"reme-ai[as]\",\n    \"pillow>=13.0.0\",\n    \"claude-agent-sdk>=0.2.174\",\n    \"openai-codex>=0.163.0\",\n    \"pproxy>=2.7.9,<3\",\n    \"faiss-cpu>=1.15.1\",\n    \"zvec>=0.8.0\",\n    \"jieba>=0.42.1\",\n    \"rjieba>=0.2.2\",\n    \"neo4j>=6.4.1\",\n    \"networkx>=3.6.1; python_version < '3.12'\",\n    \"networkx>=3.6; python_full_version == '3.14.1'\",\n    \"networkx>=3.7; python_version >= '3.12' and python_full_version != '3.14.1'\",\n    \"polars>=2.1.0\",\n    \"reme_studio\",\n]\nqwen-tokenizer = [\n    \"tokenizers>=0.23.3,<1\",\n]\nimage-heif = [\n    \"pillow>=13.0.0\",\n    \"pillow-heif>=1.8.1\",\n]\ndev = [\n    \"packaging>=26.3\",\n    \"pre-commit>=4.7.0\",\n    \"pytest>=9.2.0\",\n    \"pytest-asyncio>=1.4.1\",\n]\nbenchmark-docker = [\n    \"reme-ai[as]\",\n    \"aiodocker>=0.27.0\",\n]\nfull = [\n    \"reme-ai[core]\",\n    \"reme-ai[qwen-tokenizer]\",\n    \"reme-ai[decision]\",\n    \"reme-ai[dev]\",\n    \"reme-ai[image-heif]\",\n]\n\n[project.urls]\nHomepage = \"https://github.com/agentscope-ai/ReMe\"\nDocumentation = \"https://reme.agentscope.io\"\nRepository = \"https://github.com/agentscope-ai/ReMe\"\n\n[project.scripts]\nreme = \"reme.reme:main\"\n\n[tool.setuptools]\npackages = { find = { where = [\".\"], include = [\"reme\", \"reme.*\", \"deploy\", \"deploy.*\"], exclude = [\"reme_studio*\"] } }\ninclude-package-data = true\n\n[tool.setuptools.package-data]\n\"*\" = [\"py.typed\", \"**/*.yaml\", \"**/*.json\"]\n\"reme.components.tokenizer\" = [\"stopwords\"]\n\"deploy.benchmark_docker\" = [\"Dockerfile.*\", \"README.md\"]\n\n[tool.setuptools.dynamic]\nversion = { attr = \"reme.__version__\" }\n\n[build-system]\nrequires = [\"setuptools>=84.2.1\", \"wheel>=0.48.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[tool.pytest.ini_options]\nasyncio_default_fixture_loop_scope = \"function\"\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\npython_functions = [\"test_*\"]\n"
    },
    {
      "path": "reme/config/default.yaml",
      "content": "service:\n  backend: http\n  web_enabled: true\n  mcp_enabled: true\n  mcp_path: /mcp\n\njobs:\n  index_update_loop:\n    backend: background\n    watch_dirs: [daily_dir, digest_dir]\n    watch_suffixes: [md]\n    steps:\n      - backend: init_changes_step\n        monitor_type: file_store\n        monitor_name: default\n        dispatch_steps: [update_index_step]\n      - backend: watch_changes_step\n        watch_mode: awatch  # Set to watch to isolate the blocking wait from AnyIO's shared thread limiter.\n        monitor_type: file_store\n        dispatch_steps:\n          - backend: update_index_step\n            persist: False\n\n  resource_watch_loop:\n    backend: background\n    watch_dirs: [resource_dir]\n    watch_suffixes: [md, txt, json, jsonl, csv, yaml, html, png, jpg, jpeg, webp, gif, bmp, tiff, heic]\n    steps:\n      - backend: init_changes_step\n        monitor_type: file_catalog\n        monitor_name: resource\n        dispatch_steps:\n          - backend: update_catalog_step\n            file_catalog: resource\n          - backend: auto_resource_step\n            dispatch_steps:\n              - auto_image_resource_step\n              - auto_text_resource_step\n      - backend: watch_changes_step\n        watch_mode: awatch\n        monitor_type: file_catalog\n        monitor_name: resource\n        dispatch_steps:\n          - backend: update_catalog_step\n            file_catalog: resource\n          - backend: auto_resource_step\n            dispatch_steps:\n              - auto_image_resource_step\n              - auto_text_resource_step\n\n  digest_watch_loop:\n    backend: background\n    watch_dirs: [daily_dir, digest_dir]\n    watch_suffixes: [md]\n    steps:\n      - backend: init_changes_step\n        monitor_type: file_catalog\n        monitor_name: digest\n        dispatch_steps:\n          - backend: update_catalog_step\n            file_catalog: digest\n          - backend: log_changes_step\n      - backend: watch_changes_step\n        watch_mode: awatch\n        monitor_type: file_catalog\n        monitor_name: digest\n        dispatch_steps:\n          - backend: update_catalog_step\n            file_catalog: digest\n          - backend: log_changes_step\n\n  dream_cron:\n    backend: cron\n    cron: \"0 23 * * *\"\n    steps:\n      - backend: dream_extract_step\n        file_catalog: dream\n        scan_days: 2\n        max_units: 5\n      - backend: dream_integrate_step\n      - backend: dream_finish_step\n        file_catalog: dream\n      - backend: auto_tag_step\n\n  optimize_index_cron:\n    backend: cron\n    cron: \"0 2 * * *\"\n    steps:\n      - backend: optimize_index_step\n\n  proactive_refresh:\n    backend: base\n    enable_serve: false\n    description: \"Refresh proactive topics once for local maintenance or debugging; not exposed by HTTP/MCP.\"\n    parameters:\n      type: object\n      properties:\n        date:\n          type: string\n          description: \"YYYY-MM-DD to refresh; defaults to today in the application's timezone\"\n          default: \"\"\n    steps:\n      - backend: proactive_extract_step\n        file_catalog: proactive\n        scan_days: 2\n        carry_forward_days: 14\n        max_carry_forward_topics: 20\n        llm_timeout_seconds: 300\n        max_chars_per_file: 60000\n        max_total_chars: 300000\n      - backend: proactive_topics_step\n        known_threshold: 0.85\n        known_threshold_calibrated_for: text-embedding-v4@1024\n        min_push_confidence: 0.5\n        max_topics: 10\n      - backend: proactive_plan_step\n      - backend: proactive_agenda_step\n      - backend: proactive_finish_step\n        file_catalog: proactive\n\n  proactive_refresh_cron:\n    backend: cron\n    cron: \"0 18 * * *\"             # once a day at 18:00\n    steps:\n      - backend: proactive_extract_step\n        file_catalog: proactive\n        scan_days: 2\n        carry_forward_days: 14\n        max_carry_forward_topics: 20\n        llm_timeout_seconds: 300\n        max_chars_per_file: 60000\n        max_total_chars: 300000\n      - backend: proactive_topics_step\n        known_threshold: 0.85\n        known_threshold_calibrated_for: text-embedding-v4@1024\n        min_push_confidence: 0.5\n        max_topics: 10\n      - backend: proactive_plan_step\n      - backend: proactive_agenda_step\n      - backend: proactive_finish_step\n        file_catalog: proactive\n\n  auto_dream:\n    backend: base\n    description: \"Auto-dream: scan today's day-index and daily notes, globally extract merged units, integrate digest units, and persist the dream catalog.\"\n    parameters:\n      type: object\n      properties:\n        date:\n          type: string\n          description: \"YYYY-MM-DD to scan; defaults to today in the dreamer's timezone\"\n          default: \"\"\n        hint:\n          type: string\n          description: \"caller guidance passed through to dream extract/integrate\"\n          default: \"\"\n        scan_days:\n          type: integer\n          description: \"number of recent daily directories to scan, ending at date\"\n          default: 2\n        max_units:\n          type: integer\n          description: \"maximum number of extracted memory units\"\n          default: 5\n    steps:\n      - backend: dream_extract_step\n        file_catalog: dream\n        scan_days: 2\n        max_units: 5\n      - backend: dream_integrate_step\n      - backend: dream_finish_step\n        file_catalog: dream\n      - backend: auto_tag_step\n\n  auto_memory:\n    backend: base\n    description: \"Auto-memory: record conversation facts into a daily note\"\n    parameters:\n      type: object\n      properties:\n        request_id:\n          type: string\n          description: \"Optional stable batch ID (1-128 characters); replay completed requests without rerunning the memory agent\"\n        messages:\n          type: array\n          description: \"messages\"\n          items:\n            type: object\n        session_id:\n          type: string\n          description: \"source conversation session identifier\"\n          default: \"\"\n        memory_hint:\n          type: string\n          description: \"optional hint\"\n        include_images:\n          type: boolean\n          description: \"Use session images with a vision-capable AgentScope model; save Base64 originals and cite sources\"\n          default: false\n        date:\n          type: string\n          description: \"YYYY-MM-DD daily note date; empty = infer from message timestamps or today\"\n          default: \"\"\n      required:\n        - messages\n    steps:\n      - backend: auto_memory_step\n      - backend: auto_tag_step\n\n  auto_memory_cc:\n    backend: base\n    description: \"Auto-memory (Claude Code): record a Claude Code session into a daily note, resolved from its session_id\"\n    parameters:\n      type: object\n      properties:\n        session_id:\n          type: string\n          description: \"Claude Code session id; its transcript is resolved from disk\"\n        memory_hint:\n          type: string\n          description: \"optional hint\"\n      required:\n        - session_id\n    steps:\n      - backend: auto_memory_cc_step\n      - backend: auto_tag_step\n\n  auto_resource:\n    backend: base\n    description: \"Auto-resource: interpret resource files into daily notes\"\n    parameters:\n      type: object\n      properties:\n        include_images:\n          type: boolean\n          description: \"Process image resource changes with a vision-capable AgentScope wrapper; false skips all image events, including deletes\"\n          default: true\n        changes:\n          type: array\n          description: \"resource change batch, each item has path/file_path and change\"\n          items:\n            type: object\n            properties:\n              path:\n                type: string\n              file_path:\n                type: string\n              change:\n                type: string\n                description: \"added/modified/deleted\"\n      required:\n        - changes\n    steps:\n      - backend: auto_resource_step\n        dispatch_steps:\n          - auto_image_resource_step\n          - auto_text_resource_step\n\n  proactive_read:\n    backend: base\n    description: \"Proactive: read daily/<date>/interests.yaml and expose the latest user-interest topics.\"\n    parameters:\n      type: object\n      properties:\n        date:\n          type: string\n          description: \"YYYY-MM-DD to read; defaults to today in the dreamer's timezone\"\n          default: \"\"\n        include_content:\n          type: boolean\n          description: \"whether to include the raw YAML content in the response answer and metadata\"\n          default: true\n        horizon_days:\n          type: integer\n          description: \"merge interests.yaml across this many recent days (1 = single-day legacy behaviour)\"\n          default: 1\n        min_confidence:\n          type: number\n          description: \"minimum topic confidence to return (default 0.4 sits safely below the 0.5 fallback; v1 topics fall back to 0.5)\"\n          default: 0.4\n    steps:\n      - backend: proactive_step\n        min_confidence: 0.4\n\n  version:\n    backend: base\n    description: \"return reme package version\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: version_step\n\n  app_config:\n    backend: base\n    description: \"return the effective application config with secrets redacted\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: app_config_step\n\n  chat:\n    backend: stream\n    description: \"Stream a read-only agent conversation over the ReMe workspace.\"\n    parameters:\n      type: object\n      properties:\n        query:\n          type: string\n          description: \"user message\"\n        session_id:\n          type: string\n          description: \"agent session to resume\"\n        system_prompt:\n          type: string\n          description: \"optional system prompt override\"\n      required:\n        - query\n    steps:\n      - backend: chat_step\n        agent_wrapper: default\n\n  health_check:\n    backend: base\n    description: \"return a concise health-check snapshot of reme components\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: health_check_step\n\n  status:\n    backend: base\n    description: \"report memory estimates for stateful data components and process RSS\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: status_step\n\n  help:\n    backend: base\n    description: \"list all registered jobs with their metadata\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: help_step\n\n#  shell:\n#    backend: base\n#    description: \"execute a shell command asynchronously in the workspace\"\n#    parameters:\n#      type: object\n#      properties:\n#        cmd:\n#          type: string\n#          description: \"shell command to execute\"\n#        shell_timeout:\n#          type: number\n#          description: \"maximum execution time in seconds\"\n#          default: 86400\n#      required:\n#        - cmd\n#    steps:\n#      - backend: shell_step\n\n  traverse:\n    backend: base\n    description: >-\n      Return a bounded wikilink graph with frontend-ready nodes and directed edges.\n    parameters:\n      type: object\n      properties:\n        path:\n          oneOf:\n            - type: string\n            - type: array\n              items:\n                type: string\n              minItems: 1\n          description: \"workspace-relative path or paths used as graph seeds\"\n        depth:\n          type: integer\n          minimum: 0\n          description: \"maximum number of wikilink hops\"\n          default: 1\n        direction:\n          type: string\n          description: >-\n            traversal direction; returned edges always preserve the original\n            wikilink source-to-target direction\n          enum:\n            - forward\n            - backward\n            - both\n          default: both\n      required:\n        - path\n    steps:\n      - backend: traverse_step\n\n  graph_snapshot:\n    backend: base\n    description: \"Return the category-rooted digest wikilink graph with daily-note leaves.\"\n    parameters:\n      type: object\n      properties: { }\n    steps:\n      - backend: graph_snapshot_step\n\n  list_tags:\n    backend: base\n    description: >-\n      List active tags with file counts. Returns {total_tags, total_pages, page, range, items}; range is the inclusive\n      1-based item range and each item is [tag, file_count]. A page past the end returns empty items and range [0, 0].\n    parameters:\n      type: object\n      properties:\n        page:\n          type: integer\n          minimum: 1\n          default: 1\n          description: \"1-based page; values past the end return an empty page\"\n        order_by:\n          type: string\n          enum: [tag, file_count]\n          default: tag\n          description: \"sort by tag or file count\"\n        order:\n          type: string\n          enum: [asc, desc]\n          description: \"defaults to asc for tag, desc for file_count\"\n        page_size:\n          type: integer\n          minimum: 1\n          maximum: 1000\n          default: 100\n          description: \"items per page\"\n    steps:\n      - backend: list_tags_step\n\n  reindex:\n    backend: base\n    description: \"rebuild BM25, embedding, and/or tag indexes without rescanning workspace files\"\n    parameters:\n      type: object\n      properties:\n        scope:\n          type: string\n          enum: [all, bm25, embedding, tag]\n          default: all\n    steps:\n      - backend: reindex_step\n\n  search:\n    backend: base\n    description: \"Hybrid workspace search (vector + BM25, RRF-fused).\"\n    parameters:\n      type: object\n      properties:\n        query:\n          type: string\n          description: \"search query\"\n        limit:\n          type: integer\n          description: \"max results\"\n          default: 5\n        min_score:\n          type: number\n          description: >-\n            Minimum returned score; 0 disables filtering (recommended).\n            Uses native vector or BM25 scores when only one branch has hits,\n            and rank-based RRF scores (at most 1/61, about 0.01639) when both have hits.\n            The scale can change per query; this is not a normalized relevance threshold.\n          default: 0.0\n        tags:\n          type: array\n          items:\n            type: string\n          description: \"optional tags filter; a file matches when it contains at least one valid tag\"\n          default: []\n        start_date:\n          type: string\n          description: \"optional inclusive start date filter (YYYY-MM-DD); results earlier than this date are excluded\"\n        end_date:\n          type: string\n          description: \"optional inclusive end date filter (YYYY-MM-DD); results later than this date are excluded\"\n      required:\n        - query\n    steps:\n      - backend: search_step\n        vector_weight: 0.7\n        candidate_multiplier: 5.0\n        expand_links: true\n        max_links_per_direction: 10\n\n  node_search:\n    backend: base\n    description: \"Digest node recall — given a candidate abstraction's name+description, surface existing digest nodes similar enough to either dedup against or link to as related.\"\n    parameters:\n      type: object\n      properties:\n        query:\n          type: string\n          description: \"search query\"\n        limit:\n          type: integer\n          description: \"max digest nodes to return\"\n          default: 20\n      required:\n        - query\n    steps:\n      - backend: node_search_step\n        vector_weight: 0.7\n        candidate_multiplier: 5.0\n\n  daily_list:\n    backend: base\n    description: >-\n      List daily notes without changing files or indexes. Defaults to all notes for today; date selects one day.\n      Alternatively, start_date and end_date select an inclusive range, newest day first then path ascending.\n      Range queries or explicit page/page_size opt into pagination (defaults: page 1, page_size 100).\n      Metadata adds page, page_size, total_notes and total_pages; count and notes describe the returned page.\n    parameters:\n      type: object\n      properties:\n        date:\n          type: string\n          description: \"YYYY-MM-DD; empty = today when no range is given; cannot be combined with a range\"\n          default: \"\"\n        start_date:\n          type: string\n          description: \"inclusive YYYY-MM-DD range start; requires end_date; cannot be combined with date\"\n        end_date:\n          type: string\n          description: \"inclusive YYYY-MM-DD range end; requires start_date\"\n        page:\n          type: integer\n          minimum: 1\n          description: \"optional 1-based page; defaults to 1 when paginating; past the end returns no notes\"\n        page_size:\n          type: integer\n          minimum: 1\n          maximum: 1000\n          description: \"optional notes per page; defaults to 100 when paginating\"\n    steps:\n      - backend: daily_list_step\n\n  daily_reindex:\n    backend: base\n    description: \"Rebuild the day-index page daily/<date>.md.\"\n    parameters:\n      type: object\n      properties:\n        date:\n          type: string\n          description: \"YYYY-MM-DD; empty = today\"\n          default: \"\"\n    steps:\n      - backend: daily_reindex_step\n\n  frontmatter_delete:\n    backend: base\n    description: \"Drop keys from a file's frontmatter.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n        keys:\n          type: array\n          description: \"keys to remove\"\n          items:\n            type: string\n      required:\n        - path\n        - keys\n    steps:\n      - backend: frontmatter_delete_step\n\n  frontmatter_read:\n    backend: base\n    description: \"Read a file's frontmatter, one key: value per line.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n      required:\n        - path\n    steps:\n      - backend: frontmatter_read_step\n\n  frontmatter_update:\n    backend: base\n    description: \"Merge key-value pairs into a Markdown file's frontmatter while preserving its body and unrelated fields.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n        metadata:\n          type: object\n          description: \"key-values to merge\"\n      required:\n        - path\n        - metadata\n    steps:\n      - backend: frontmatter_update_step\n\n  stat:\n    backend: base\n    description: \"Stat path (size, mtime, exists, is_dir, is_file).\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n      required:\n        - path\n    steps:\n      - backend: stat_step\n\n  list:\n    backend: base\n    description: \"List files under a workspace path.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative dir; empty = root\"\n          default: \"\"\n        recursive:\n          type: boolean\n          description: \"recurse\"\n          default: false\n        sort_by:\n          type: string\n          enum:\n            - mtime\n          description: \"optional ordering; mtime returns most recently modified files first\"\n        extensions:\n          type: array\n          items:\n            type: string\n          description: \"optional extension allowlist applied before sorting and limiting\"\n        limit:\n          type: integer\n          description: \"max results\"\n          default: 100\n    steps:\n      - backend: list_step\n\n  move:\n    backend: base\n    description: \"Move / rename a workspace file; rewrites inbound wikilinks by default.\"\n    parameters:\n      type: object\n      properties:\n        src_path:\n          type: string\n          description: \"workspace-relative source\"\n        dst_path:\n          type: string\n          description: \"workspace-relative destination\"\n        overwrite:\n          type: boolean\n          description: \"overwrite if dst exists\"\n          default: false\n        retarget:\n          type: boolean\n          description: \"rewrite [[src]] → [[dst]] across the workspace\"\n          default: true\n      required:\n        - src_path\n        - dst_path\n    steps:\n      - backend: move_step\n\n  delete:\n    backend: base\n    description: \"Delete a workspace file or folder; returns surviving inbound wikilinks.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n      required:\n        - path\n    steps:\n      - backend: delete_step\n\n  read:\n    backend: base\n    description: \"Read a markdown file under the workspace.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path; markdown only\"\n        start_line:\n          type: integer\n          description: \"first line (1-based, inclusive)\"\n        end_line:\n          type: integer\n          description: \"last line (1-based, inclusive)\"\n      required:\n        - path\n    steps:\n      - backend: read_step\n        with_neighbors: false\n        max_neighbors_per_direction: 10\n\n  load:\n    backend: base\n    description: \"Load a complete text file for the local editor without agent-output truncation.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n      required:\n        - path\n    steps:\n      - backend: load_step\n        max_bytes: 5242880\n\n  read_image:\n    backend: base\n    description: \"Read an image file as base64 (workspace-relative path).\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: >-\n            workspace-relative path; common image formats supported\n            (png/jpg/jpeg/webp/gif/bmp/tiff/heic)\n      required:\n        - path\n    steps:\n      - backend: read_image_step\n        max_bytes: 5242880\n\n  write:\n    backend: base\n    description: \"Write a markdown file (create or overwrite) with name/description frontmatter.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path; markdown only\"\n        name:\n          type: string\n          description: \"frontmatter name\"\n        description:\n          type: string\n          description: \"frontmatter description\"\n        content:\n          type: string\n          description: \"body\"\n        metadata:\n          type: object\n          description: \"Optional extra frontmatter fields (md only).\"\n      required:\n        - path\n        - name\n        - description\n        - content\n    steps:\n      - backend: write_step\n\n  save:\n    backend: base\n    description: \"Save text verbatim, optionally rejecting external changes since the file was opened.\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n        content:\n          type: string\n          description: \"complete file content, including frontmatter\"\n        expected_mtime:\n          type: string\n          description: \"optional ISO mtime returned by stat\"\n      required:\n        - path\n        - content\n    steps:\n      - backend: save_step\n\n  daily_write:\n    backend: base\n    description: \"Write a daily markdown note with conversation source frontmatter.\"\n    parameters:\n      type: object\n      properties:\n        name:\n          type: string\n          description: \"daily note filename stem and frontmatter name\"\n        description:\n          type: string\n          description: \"frontmatter description\"\n        session_id:\n          type: string\n          description: \"source conversation session identifier\"\n        content:\n          type: string\n          description: \"body\"\n        date:\n          type: string\n          description: \"YYYY-MM-DD daily note date; empty = today\"\n          default: \"\"\n        metadata:\n          type: object\n          description: \"Optional extra frontmatter fields.\"\n      required:\n        - name\n        - description\n        - session_id\n        - content\n    steps:\n      - backend: daily_write_step\n\n  edit:\n    backend: base\n    description: \"Find-and-replace in a markdown file (all occurrences).\"\n    parameters:\n      type: object\n      properties:\n        path:\n          type: string\n          description: \"workspace-relative path\"\n        old:\n          type: string\n          description: \"text to find\"\n        new:\n          type: string\n          description: \"replacement\"\n          default: \"\"\n      required:\n        - path\n        - old\n        - new\n    steps:\n      - backend: edit_step\n\ncomponents:\n  tokenizer:\n    default:\n      backend: regex\n\n#  as_embedding:\n#    default:\n#      backend: ${EMBEDDING_BACKEND:-op