   approval_mode: auto_review\n      sandbox: full-access\n\n  file_graph:\n    default:\n      backend: local\n\n  file_catalog:\n    default:\n      backend: local\n    resource:\n      backend: local\n    digest:\n      backend: local\n    dream:\n      backend: local\n    proactive:\n      backend: local\n\n  file_chunker:\n    markdown:\n      backend: markdown\n      supported_extensions: [ \"md\" ]\n      embed_toc: true\n      max_ast_sections: 100\n      include_frontmatter_in_metadata: false\n      include_frontmatter_keys_in_metadata: []  # empty = all non-empty frontmatter keys\n    json:\n      backend: json\n      supported_extensions: [ \"json\" ]\n    jsonl:\n      backend: jsonl\n      supported_extensions: [ \"jsonl\" ]  # noqa: keep #314 chunker scope intact after #325\n    default:\n      backend: default\n      supported_extensions: [\"txt\",\"log\"]\n\n  keyword_index:\n    default:\n      backend: bm25\n      tokenizer: default\n\n  tag_index:\n    default:\n      backend: local\n      tag_key: memory_tags\n      max_tags_per_file: 3\n      max_tag_length: 64\n\n  file_store:\n    default:\n      backend: local\n      # backend: faiss\n      store_name: local\n#      embedding_store: default\n      embedding_store: \"\"\n      keyword_index: default\n      file_graph: default\n      tag_index: default\n"
